CREATE OR REPLACE FUNCTION public.dp_voice_set_my_tracks(tracks text[], tongues boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text[]:=coalesce(tracks,'{}');
begin
 if auth.uid() is null or not dp_private.voice_member(auth.uid()) then raise exception 'Voice enrollment required'; end if;
 if not (t <@ array['worship_leadership','spontaneous_expression','prophetic_worship']) then raise exception 'Unknown track'; end if;
 insert into dp_voice_profiles(student_id,selected_tracks,tongues_requested) values(auth.uid(),t,coalesce(tongues,false) and 'prophetic_worship'=any(t))
 on conflict(student_id) do update set selected_tracks=excluded.selected_tracks,
  approved_tracks=array(select x from unnest(dp_voice_profiles.approved_tracks) x where x=any(excluded.selected_tracks)),
  tongues_requested=excluded.tongues_requested,updated_at=now();
end $function$;
revoke all on function public.dp_voice_set_my_tracks(tracks text[], tongues boolean) from public, anon, authenticated, service_role;
grant execute on function public.dp_voice_set_my_tracks(tracks text[], tongues boolean) to postgres;
grant execute on function public.dp_voice_set_my_tracks(tracks text[], tongues boolean) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_voice_submit_intake(a jsonb, requested_tracks text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare iid uuid:=gen_random_uuid();
begin
 if auth.uid() is null or not dp_private.voice_member(auth.uid()) then raise exception 'Voice enrollment required'; end if;
 insert into dp_voice_intakes(id,student_id,source,answers) values(iid,auth.uid(),'hub',a);
 perform public.dp_voice_set_my_tracks(requested_tracks, false);
 return iid;
end $function$;
revoke all on function public.dp_voice_submit_intake(a jsonb, requested_tracks text[]) from public, anon, authenticated, service_role;
grant execute on function public.dp_voice_submit_intake(a jsonb, requested_tracks text[]) to postgres;
grant execute on function public.dp_voice_submit_intake(a jsonb, requested_tracks text[]) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone, import_key text)
 RETURNS TABLE(id uuid, duplicate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare iid uuid:=gen_random_uuid(); t text[]:=coalesce(requested_tracks,'{}'); existing uuid; newest timestamptz; sub timestamptz:=coalesce(submitted,now());
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 if not dp_private.voice_member(student) then raise exception 'That person is not enrolled in Voice'; end if;
 if not (t <@ array['worship_leadership','spontaneous_expression','prophetic_worship']) then raise exception 'Unknown track'; end if;
 if length(coalesce(import_key,''))<16 then raise exception 'An import key is required'; end if;
 select i.id into existing from dp_voice_intakes i where i.student_id=student and i.import_key=dp_voice_import_intake.import_key;
 if existing is not null then return query select existing,true; return; end if;
 select max(i.submitted_at) into newest from dp_voice_intakes i where i.student_id=student;
 insert into dp_voice_intakes(id,student_id,source,answers,submitted_at,imported_by,import_key) values(iid,student,'google_forms_import',a,sub,auth.uid(),import_key);
 if newest is null or sub>=newest then
  insert into dp_voice_profiles(student_id,selected_tracks) values(student,t)
  on conflict(student_id) do update set selected_tracks=excluded.selected_tracks,
   approved_tracks=array(select x from unnest(dp_voice_profiles.approved_tracks) x where x=any(excluded.selected_tracks)),
   tongues_requested=dp_voice_profiles.tongues_requested and 'prophetic_worship'=any(excluded.selected_tracks),updated_at=now();
 end if;
 return query select iid,false;
end $function$;
revoke all on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone, import_key text) from public, anon, authenticated, service_role;
grant execute on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone, import_key text) to postgres;
grant execute on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone, import_key text) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_assessment_assign(student uuid, assessment_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare aid uuid:=gen_random_uuid(); prof dp_voice_profiles;
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 if not dp_private.voice_member(student) then raise exception 'That person is not enrolled in Voice'; end if;
 if assessment_kind='hearing_god' then raise exception 'How Does God Speak to You? cannot be assigned until its source wording is supplied'; end if;
 if assessment_kind not in ('personal_time','creative_expression') then raise exception 'Unknown assessment'; end if;
 if assessment_kind='personal_time' then
  select * into prof from dp_voice_profiles where student_id=student;
  if not found or not 'prophetic_worship'=any(prof.selected_tracks) then raise exception 'Only students who chose Prophetic Worship Development can be given this'; end if;
 end if;
 insert into dp_voice_assessments(id,student_id,kind,assigned_by) values(aid,student,assessment_kind,auth.uid());
 return aid;
end $function$;
revoke all on function public.dp_assessment_assign(student uuid, assessment_kind text) from public, anon, authenticated, service_role;
grant execute on function public.dp_assessment_assign(student uuid, assessment_kind text) to postgres;
grant execute on function public.dp_assessment_assign(student uuid, assessment_kind text) to authenticated;
commit;
